INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'music_interest','courses','c_d05ab6f93e55',t.id FROM offer_courses t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='music_interest' AND t.source='template' AND t.version=1 AND t.name='声乐一对一60分钟' AND s.pack_version='0.1';
